return {api_version=1,id="LOOT_367",name="Drywhisker Armorer",text="<b>Battlecry:</b> For each enemy minion, gain 2 Armor.",set="LOOTAPALOOZA",type="minion",class="warrior",rarity="common",cost=2,attack=2,health=2,keywords={"battlecry"},on_battlecry=function(ctx,self)local n=0;for _,e in ipairs(ctx:enemy_characters(self))do if ctx:entity(e).type=="minion"then n=n+1 end end;ctx:gain_armor(ctx:controller(self),2*n)end}
